# ============================================================
# AEGIS NIDS - STEP 5: Flow Engine Integration
# ============================================================
# Bridges the Flow Engine with the Event Fabric:
#   - processEvent(event) updates FlowTable state from CanonicalEvent
#   - Returns FlowContext (snapshot) for detection layer
#   - Host events (source_ip=0, is_pipe=1) are skipped
#   - Network events upsert by 5-tuple (src/dst IP+port, protocol)
#   - updateRiskScore() lets detection layer annotate flows
#   - purgeExpired() called periodically for maintenance
#
# Detection layer now has stateful context: packet_count, byte_count,
# flow age, risk score — enabling port-scan detection, beaconing
# detection, slow-data-exfiltration patterns, etc.
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 5 - Flow Engine Integration"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
        Write-Host "  [MKDIR] Created: $Dir"
    }
    $BackupPath = "$FullPath.step5_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/flow_integration.zig (flow_integration.zig, 656 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/flow_integration.zig" -ExpectedLines 656 -Base64Content $B64_1
Write-Host ""

# File 2: core/nids_main.zig (nids_main.zig, 241 lines)
$B64_2 = ''
Deploy-File -RelativePath "core/nids_main.zig" -ExpectedLines 241 -Base64Content $B64_2
Write-Host ""

# File 3: build.zig (build.zig, 80 lines)
$B64_3 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 80 -Base64Content $B64_3
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) {
    Write-Host "[BUILD] FAILED (exit $buildExit)"
    exit 1
}
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test (uses ErrorActionPreference=Continue)..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

Write-Host "============================================================"
Write-Host "STEP 5 COMPLETE: Flow Engine Integration"
Write-Host "============================================================"
Write-Host ""
Write-Host "Files deployed:"
Write-Host "  core/flow_integration.zig  (NEW, 656 lines)"
Write-Host "    - FlowContext struct: value-type snapshot (race-safe)"
Write-Host "      is_new_flow, packet_count, byte_count, risk_score, session_id"
Write-Host "    - processEvent(event): update FlowTable + return FlowContext"
Write-Host "    - processEventWithFlowPtr(): variant returning flow pointer"
Write-Host "    - updateRiskScore(key, score): detection annotates flows"
Write-Host "    - purgeExpired(): maintenance (call periodically)"
Write-Host "    - IntegrationStats: events processed, flows created/updated"
Write-Host "    - Host events (source_ip=0 or is_pipe=1) are skipped"
Write-Host "    - 14 STEP5 tests: lifecycle, host/network events, multi-flow,"
Write-Host "      risk score persistence, port-scan detection scenario"
Write-Host ""
Write-Host "  core/nids_main.zig         (REPLACE, 241 lines)"
Write-Host "    - Imports flow_integration module"
Write-Host "    - Calls flow_int.init() after flow_table (legacy kept)"
Write-Host "    - defer flow_int.shutdown() for clean exit"
Write-Host ""
Write-Host "  build.zig                  (REPLACE, 80 lines)"
Write-Host "    - Added core/flow_integration.zig to test_files (23 entries)"
Write-Host ""
Write-Host "Integration design:"
Write-Host "  - flow_integration is a process-wide singleton (single FlowTable)"
Write-Host "  - FlowContext is a value type (snapshot — caller can keep it across yields)"
Write-Host "  - Detection layer calls processEvent() then uses ctx.packet_count"
Write-Host "    to escalate severity (e.g., 1000th packet from same flow)"
Write-Host ""
Write-Host "Total STEP 5 tests: ~14 (flow_integration.zig)"
Write-Host "Total Zig tests now: ~275 (was ~260 after STEP 4)"
Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"feat: step 5 - flow engine integration (event-driven context)`""
Write-Host "  git push"
